# Bank zadań autorskich — wiek XIX (partia łatająca luki: rozstrzygnij + uzasadnij, wybór, P/F, chronologia).
# B(tytuł, materiał, *zadania) — wiązka; T(typ, punkty, polecenie, odpowiedź, omówienie) — zadanie.
# Zasada dystraktorów: każda błędna odpowiedź to postać/wydarzenie z tej samej epoki i kontekstu.
BANK = {}

BANK['xix-wiek'] = [
 B('Królestwo Polskie w świetle konstytucji z 1815 r.',
   'Tekst (autorski, na podstawie konstytucji Królestwa Polskiego z 1815 r.). Królestwo Polskie jest na zawsze połączone z Cesarstwem Rosyjskim. Koroną polską dziedzicznie włada cesarz Wszechrosji. Król mianuje namiestnika, który w jego zastępstwie kieruje administracją. Władzę ustawodawczą sprawuje król razem z sejmem złożonym z senatu i izby poselskiej. Królestwo ma własne wojsko, skarb i administrację, a językiem urzędowym jest polski. Sprawy zagraniczne należą wyłącznie do monarchy.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy Królestwo Polskie w świetle konstytucji z 1815 r. było państwem w pełni suwerennym. Odpowiedź uzasadnij, odwołując się do tekstu.',
     'Nie. Królestwo było połączone z Rosją unią personalną (królem był car), a polityka zagraniczna należała wyłącznie do monarchy — Królestwo nie prowadziło własnej polityki zagranicznej.',
     'W zadaniach o suwerenności szukaj w tekście dwóch rzeczy: kto jest władcą i kto decyduje o sprawach zagranicznych. Własne wojsko, skarb i język świadczą o autonomii, ale nie o suwerenności — to częsta pułapka.'),
   T('abcd', 1, 'Dokończ zdanie. Pierwszym namiestnikiem Królestwa Polskiego był\nA. wielki książę Konstanty.\nB. Józef Zajączek.\nC. Adam Jerzy Czartoryski.\nD. Józef Chłopicki.',
     'B',
     'Zajączek był namiestnikiem w latach 1815–1826. Wielki książę Konstanty dowodził armią Królestwa (nie był namiestnikiem). Czartoryski liczył na to stanowisko, ale go nie dostał. Chłopicki to generał, później dyktator powstania listopadowego.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Konstytucja z 1815 r. przewidywała dwuizbowy sejm.\n2. Kaliszanie domagali się przestrzegania postanowień konstytucji.\n3. Pierwszy sejm Królestwa Polskiego zwołano dopiero w 1830 r.',
     '1 – P, 2 – P, 3 – F.',
     'Pierwszy sejm zebrał się w 1818 r. Kaliszanie (bracia Niemojowscy) to legalna opozycja, która broniła konstytucji, a nie dążyła do powstania.')),

 B('Spór w czasie powstania listopadowego',
   'Tekst (autorski, w duchu wystąpień członków Towarzystwa Patriotycznego, 1831 r.). Kto dziś mówi o rokowaniach z carem, ten zdradza sprawę narodu. Car nigdy nie odda nam wolności z własnej woli. Jedyną drogą jest wojna prowadzona wszystkimi siłami, z udziałem ludu, któremu trzeba obiecać ziemię. Nie możemy dłużej znosić wodzów, którzy boją się zwycięstwa.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy tekst wyraża poglądy obozu zachowawczego (arystokratycznego) czy radykalnego w czasie powstania listopadowego. Uzasadnij, odwołując się do tekstu.',
     'Radykalnego — autor odrzuca rokowania z carem, wzywa do wojny wszystkimi siłami i do pozyskania chłopów obietnicą ziemi, krytykuje ostrożnych dowódców.',
     'Obóz zachowawczy (A.J. Czartoryski, Chłopicki) liczył na kompromis z carem lub pomoc dyplomatyczną i nie chciał reform społecznych. Radykałowie (Lelewel, Mochnacki, Towarzystwo Patriotyczne) chcieli wojny totalnej i reform. Słowa kluczowe: „rokowania” i „lud/ziemia”.'),
   T('uporzadkuj', 1, 'Uporządkuj chronologicznie wydarzenia powstania listopadowego.\nA. bitwa pod Ostrołęką\nB. detronizacja Mikołaja I przez sejm\nC. objęcie dyktatury przez gen. Józefa Chłopickiego\nD. bitwa pod Olszynką Grochowską',
     'C, B, D, A.',
     'Chłopicki: grudzień 1830 → detronizacja: 25 stycznia 1831 → Olszynka Grochowska: 25 lutego 1831 → Ostrołęka: 26 maja 1831. Kotwica: detronizacja i Grochów wypadają w tym samym dniu miesiąca (25.), styczeń i luty.')),

 B('Wiosna Ludów na ziemiach polskich',
   'Tekst (autorski). W kwietniu 1848 r. w Jarosławcu przedstawiciele polskiego komitetu narodowego i władz pruskich zawarli ugodę. Polacy mieli rozwiązać część obozów zbrojnych, a w zamian Prusy obiecały „reorganizację narodową” części Wielkiego Księstwa Poznańskiego. Kilka tygodni później oddziały polskie pod wodzą Ludwika Mierosławskiego stoczyły bitwy pod Miłosławiem i Sokołowem.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy ugoda w Jarosławcu zakończyła walki w Wielkim Księstwie Poznańskim. Uzasadnij, odwołując się do tekstu.',
     'Nie — po ugodzie doszło do bitew pod Miłosławiem i Sokołowem (kwiecień–maj 1848). Prusy nie dotrzymały obietnicy reorganizacji, a powstanie upadło dopiero po kapitulacji w maju.',
     'Tekst zawiera dowód wprost: „kilka tygodni później … stoczyły bitwy”. W zadaniach „rozstrzygnij” zawsze wskaż konkretne zdanie lub fakt z materiału.'),
   T('abcd', 1, 'Dokończ zdanie. W kwietniu 1848 r. uwłaszczenie chłopów w Galicji ogłosił\nA. cesarz Franciszek Józef I.\nB. gubernator Franz Stadion.\nC. kanclerz Klemens Metternich.\nD. namiestnik Agenor Gołuchowski.',
     'B',
     'Stadion ogłosił uwłaszczenie 22 kwietnia 1848 r., by uprzedzić polskich działaczy, którzy chcieli zrobić to w imieniu narodu. Franciszek Józef objął tron dopiero w grudniu 1848 r., Metternich upadł w marcu 1848 r., a Gołuchowski był namiestnikiem później.')),

 B('Przed wybuchem powstania styczniowego',
   'Tekst (autorski, program jednego z obozów politycznych, 1862 r.). Kraj nie jest gotowy do walki. Najpierw trzeba odbudować instytucje, wzmocnić gospodarkę i przekonać Europę do sprawy polskiej. Sprawę chłopską należy rozwiązać przez oczynszowanie, a następnie uwłaszczenie za odszkodowaniem dla właścicieli ziemskich. Przedwczesne powstanie przyniesie tylko klęskę i represje.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy tekst wyraża program „białych” czy „czerwonych”. Uzasadnij, odwołując się do dwóch elementów tekstu.',
     '„Białych” — autor odrzuca przedwczesne powstanie i stawia na pomoc Europy oraz pracę nad instytucjami, a uwłaszczenie ma nastąpić za odszkodowaniem dla ziemian.',
     'Biali: ziemiaństwo i burżuazja, uwłaszczenie za odszkodowaniem, liczenie na dyplomację. Czerwoni: szybkie powstanie, uwłaszczenie bez odszkodowania, pozyskanie chłopów. Do pełnego uzasadnienia wystarczą dwa z tych elementów.'),
   T('abcd', 1, 'Dokończ zdanie. Bezpośrednią przyczyną wybuchu powstania styczniowego było\nA. wprowadzenie stanu wojennego w Królestwie Polskim.\nB. krwawe stłumienie manifestacji patriotycznych w Warszawie.\nC. branka do wojska rosyjskiego przeprowadzona z inicjatywy Aleksandra Wielopolskiego.\nD. zamknięcie Szkoły Głównej Warszawskiej.',
     'C',
     'Branka (styczeń 1863) miała usunąć z miast młodzież związaną z konspiracją — i to przesądziło o terminie wybuchu. Stan wojenny (1861) i manifestacje (1860–1861) to przyczyny pośrednie. Szkołę Główną zamknięto po powstaniu (1869).'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Powstanie wybuchło w nocy z 22 na 23 stycznia 1863 r.\n2. Rząd Narodowy działał jako państwo podziemne: miał administrację, podatki i prasę.\n3. Romuald Traugutt został stracony na stokach Cytadeli warszawskiej w 1864 r.',
     '1 – P, 2 – P, 3 – P.',
     'Uwaga: w zadaniach P/F wszystkie zdania mogą być prawdziwe — nie zakładaj, że któreś musi być fałszywe.')),

 B('Zjednoczenie Niemiec',
   'Tekst (fragment przemówienia Ottona von Bismarcka w pruskim parlamencie, 1862 r., w przekładzie). Nie przez mowy i uchwały większości rozstrzygają się wielkie sprawy naszych czasów — to był błąd lat 1848 i 1849 — lecz przez żelazo i krew.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy zjednoczenie Niemiec przebiegło zgodnie z zapowiedzią z przemówienia. Uzasadnij, odwołując się do faktów.',
     'Tak — Niemcy zjednoczyły się w wyniku trzech wojn prowadzonych przez Prusy: z Danią (1864), z Austrią (1866) i z Francją (1870–1871), a nie w wyniku działań parlamentu.',
     '„Błąd lat 1848 i 1849” to nawiązanie do parlamentu frankfurckiego, który próbował zjednoczyć Niemcy drogą uchwał i poniósł klęskę. Do uzasadnienia wystarczą dwie z trzech wojen z datami.'),
   T('abcd', 1, 'Dokończ zdanie. Cesarstwo Niemieckie proklamowano w 1871 r. w\nA. Berlinie.\nB. Frankfurcie nad Menem.\nC. Wersalu.\nD. Poczdamie.',
     'C',
     'Proklamacja w Sali Lustrzanej w Wersalu (18 stycznia 1871 r.) była upokorzeniem pokonanej Francji. Frankfurt to siedziba parlamentu z 1848 r. Wersal wróci w 1919 r. — tam podpisano traktat kończący I wojnę światową.')),

 B('Polityka pruska wobec Polaków',
   'Tekst (autorski). W latach siedemdziesiątych XIX w. władze pruskie przejęły nadzór nad szkołami, usunęły język polski z nauczania większości przedmiotów i zaczęły usuwać duchownych sprzeciwiających się nowym przepisom. Arcybiskup gnieźnieński i poznański trafił do więzienia. Polityka ta była częścią walki kanclerza z wpływami Kościoła katolickiego w całych Niemczech.',
   T('abcd', 1, 'Dokończ zdanie. Arcybiskupem gnieźnieńskim i poznańskim uwięzionym w okresie opisanym w tekście był\nA. Zygmunt Szczęsny Feliński.\nB. Florian Stablewski.\nC. Mieczysław Ledóchowski.\nD. Edmund Dalbor.',
     'C',
     'Ledóchowski został uwięziony w 1874 r. Feliński był arcybiskupem warszawskim zesłanym przez Rosjan po 1863 r. — to dystraktor z innego zaboru. Stablewski i Dalbor rządzili archidiecezją później.'),
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy strajk dzieci we Wrześni (1901) był częścią polityki opisanej w tekście. Uzasadnij.',
     'Nie — tekst opisuje Kulturkampf (lata 70. XIX w.), wymierzony głównie w Kościół. Strajk we Wrześni był reakcją na późniejszą germanizację szkół (nauka religii po niemiecku) na początku XX w.',
     'Kulturkampf i germanizacja często się nakładają, ale CKE oczekuje rozróżnienia: Kulturkampf = walka z Kościołem (1871–1878), Września 1901 i Rota 1908 = germanizacja szkoły i ziemi (Komisja Kolonizacyjna, ustawa o „nowych osadach”).'),
   T('abcd', 1, 'Dokończ zdanie. Wiersz rozpoczynający się słowami „Nie rzucim ziemi, skąd nasz ród” napisała\nA. Eliza Orzeszkowa.\nB. Maria Konopnicka.\nC. Gabriela Zapolska.\nD. Maria Rodziewiczówna.',
     'B',
     '„Rota” Konopnickiej (1908) była odpowiedzią na pruską politykę germanizacji. Orzeszkowa i Rodziewiczówna to prozaiczki pozytywizmu, Zapolska — dramatopisarka. Wszystkie żyły w tym samym okresie, dlatego to dobre dystraktory.')),

 B('Program pozytywistów',
   'Tekst (autorski, w duchu publicystyki warszawskiej po 1864 r.). Skończył się czas szabel i spisków. Nasza siła leży w fabrykach, w handlu, w szkołach elementarnych, w każdym dobrze prowadzonym gospodarstwie. Musimy uczyć czytać i pisać lud, który dotąd nie znał litery. Zwycięstwa, które odniesiemy pracą, nie odbierze nam żaden zaborca.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy autor tekstu był zwolennikiem programu romantycznego. Uzasadnij, odwołując się do tekstu.',
     'Nie — autor odrzuca walkę zbrojną („czas szabel i spisków”) i stawia na pracę gospodarczą (fabryki, handel) i oświatę ludu, czyli program pozytywistyczny.',
     'Romantyzm = walka zbrojna, poświęcenie, mesjanizm. Pozytywizm = praca organiczna i praca u podstaw. Tekst zawiera oba hasła pozytywistów, więc uzasadnienie może wskazać każde z nich.'),
   T('abcd', 1, 'Dokończ zdanie. Hasło „pracy u podstaw” oznaczało przede wszystkim\nA. rozwój przemysłu, handlu i rzemiosła.\nB. szerzenie oświaty i podnoszenie poziomu życia najuboższych warstw społeczeństwa.\nC. tworzenie spółek akcyjnych i banków ziemskich.\nD. budowanie zaplecza do przyszłej walki zbrojnej.',
     'B',
     'Najczęstsza pomyłka: A to „praca organiczna” (rozwój całego „organizmu” społecznego: gospodarki i instytucji). „Praca u podstaw” to oświata ludu — chłopów i robotników.')),

 B('Rewolucja 1905–1907 w Królestwie Polskim',
   'Tekst (autorski, w duchu publicystyki jednego z polskich stronnictw, 1905 r.). Strajki i zamachy niszczą kraj i dają carowi pretekst do represji. Nie wolno popierać rewolucji, która prowadzi do anarchii. Trzeba wykorzystać ustępstwa władz, wybrać polskich posłów do Dumy i walczyć tam o autonomię Królestwa oraz o polską szkołę.',
   T('rozstrzygnij', 1, 'Rozstrzygnij, czy tekst wyraża stanowisko Narodowej Demokracji czy PPS. Uzasadnij, odwołując się do tekstu.',
     'Narodowej Demokracji — autor potępia strajki i rewolucję, a proponuje działanie legalne: udział w wyborach do Dumy i walkę o autonomię Królestwa.',
     'Endecja (Dmowski) w 1905 r. była przeciw rewolucji i za ugodą z Rosją w sprawie autonomii. PPS (Piłsudski) popierała strajki i walkę zbrojną (Organizacja Bojowa). Słowo-klucz: „Duma”.'),
   T('abcd', 1, 'Dokończ zdanie. Jednym ze skutków rewolucji 1905–1907 w Królestwie Polskim było\nA. przywrócenie konstytucji z 1815 r.\nB. zgoda władz na prywatne szkoły z polskim językiem nauczania.\nC. przyznanie Królestwu autonomii na wzór Galicji.\nD. zniesienie cenzury i ograniczeń dla polskiej prasy.',
     'B',
     'Władze zgodziły się na polskie szkoły prywatne (działała m.in. Polska Macierz Szkolna, szybko zdelegalizowana). Autonomii ani konstytucji nie przywrócono, a cenzura złagodniała tylko częściowo.')),

 B('Świat w drugiej połowie XIX w.',
   'Zestawienie (autorskie). A — kapitulacja wojsk konfederackich pod Appomattox; B — początek ery Meiji w Japonii; C — konferencja berlińska dzieląca strefy wpływów w Afryce; D — kongres berliński po wojnie rosyjsko-tureckiej.',
   T('uporzadkuj', 1, 'Uporządkuj wydarzenia A–D chronologicznie.',
     'A, B, D, C.',
     'Appomattox: 1865 → Meiji: 1868 → kongres berliński: 1878 → konferencja berlińska: 1884–1885. Uwaga: „kongres” (1878, Bałkany) i „konferencja” (1884–1885, Afryka) w Berlinie to dwa różne wydarzenia — CKE lubi je mieszać.'),
   T('abcd', 1, 'Dokończ zdanie. Wojna secesyjna w Stanach Zjednoczonych zakończyła się\nA. bitwą pod Gettysburgiem.\nB. ogłoszeniem Proklamacji Emancypacji.\nC. kapitulacją gen. Roberta E. Lee pod Appomattox.\nD. zabójstwem prezydenta Abrahama Lincolna.',
     'C',
     'Gettysburg (1863) to punkt zwrotny, nie koniec. Proklamacja Emancypacji też pochodzi z 1863 r. Lincoln zginął kilka dni po kapitulacji Lee (kwiecień 1865), więc to najbardziej podchwytliwy dystraktor.'),
   T('pf', 1, 'Oceń prawdziwość zdań.\n1. Reformy ery Meiji modernizowały Japonię na wzór państw zachodnich.\n2. Konferencja berlińska z lat 1884–1885 dotyczyła głównie podziału Bałkanów.\n3. Trzynasta poprawka do konstytucji USA zniosła niewolnictwo.',
     '1 – P, 2 – F, 3 – P.',
     'Konferencja berlińska dotyczyła Afryki. Bałkany to kongres berliński z 1878 r. Trzynasta poprawka została ratyfikowana w 1865 r.')),
]
